    db: ScenarioDB, 
    onUpdateDb: React.Dispatch<React.SetStateAction<ScenarioDB>>,
    templates: ScenarioTemplate[], 
    onUpdateTemplates: React.Dispatch<React.SetStateAction<ScenarioTemplate[]>> 
}> = ({ db, onUpdateDb, templates, onUpdateTemplates }) => {
